            remove_reservation(chart, next);
            chart->time = r.due;
            macro(chart, (Trigger){r.timer ? TIMER_TRIGGER : EVENT_TRIGGER, r.event, r.timer});
    } else if (equal(command, "set")) {
    } else if (equal(command, "trace")) chart->trace = equal(rest, "on");
